declarations.value:
linear-gradient(
        90deg,
        var(--color-accent) 0%,
        rgb(from var(--color-accent) r g b/0.2) 60%,
        transparent 100%
    )

-24px 24px 69px -3px rgb(from var(--color-accent) r g b/0.2),
        24px -24px 69px -3px
            hsla(
                calc(var(--accent-h) + 180),
                var(--accent-s),
                var(--accent-l),
                0.13
            ),
        inset 0 0 12px rgb(from var(--color-accent) r g b/0.1)

repeating-linear-gradient(
        to bottom,
        var(--ulu-indent-guide-color) 0,
        var(--ulu-indent-guide-color) 6px,
        transparent 6px,
        transparent 10px
    )
